export const GOLDEN_SOURCE_VMID = 9000;
export const GOLDEN_TAG = "nxeon-golden";

/**
 * Parse NXEON_GOLDEN_GAME_TEMPLATE for one game family. Accepted forms:
 *   "9101"                         every game family uses 9101
 *   "minecraft:9101,valheim:9101"  only those families
 *   "minecraft:9101,*:9102"        minecraft → 9101, every other family → 9102
 * Only the golden range 9100-9199 is accepted; anything malformed is ignored
 * (→ stock template), never guessed. Per-family mapping matters because a
 * template's pre-pulled images live on every clone's disk: a Minecraft image
 * set has no business eating 3 GB of a Rust customer's plan.
 */
export function goldenTemplateVmidFromEnv(raw: string | undefined | null, family?: string | null): number | null {
  if (!raw) return null;
  const valid = (v: string): number | null => {
    const n = Number(v.trim());
    return Number.isInteger(n) && n >= 9100 && n <= 9199 ? n : null;
  };
  const text = String(raw).trim();
  if (!text.includes(":")) return valid(text);
  let wildcard: number | null = null;
  for (const part of text.split(",")) {
    const [fam, vmid] = part.split(":").map((x) => x?.trim() ?? "");
    if (!fam || !vmid) continue;
    const n = valid(vmid);
    if (n === null) continue;
    if (fam === "*") wildcard = n;
    else if (family && fam === family) return n;
  }
  return wildcard;
}

/** Size in GB of a Proxmox disk spec like "vmdata:base-9101-disk-0,discard=on,size=6G" (or "3584M"). */
export function diskSizeGBFromSpec(spec: string | null | undefined): number | null {
  const m = /(?:^|,)size=(\d+(?:\.\d+)?)([KMGT])?/.exec(String(spec ?? ""));
  if (!m) return null;
  const n = Number(m[1]);
  const unit = m[2] ?? "G";
  const gb = unit === "T" ? n * 1024 : unit === "G" ? n : unit === "M" ? n / 1024 : n / (1024 * 1024);
  return Number.isFinite(gb) ? gb : null;
}

export type GoldenTemplateConfig = {
  template?: number | string;
  tags?: string;
  scsi0?: string;
} | null;

/**
 * Decide the clone source for one provision. `nodeConfig` is the target
 * node's `GET /nodes/<node>/qemu/<golden>/config` (null if that vmid doesn't
 * exist there). Returns the vmid to clone and why, for the worker log.
 */
export function chooseCloneSource(opts: {
  baseVmid: number;
  isGame: boolean;
  goldenVmid: number | null;
  nodeConfig: GoldenTemplateConfig;
  targetDiskGB: number;
}): { vmid: number; golden: boolean; reason: string } {
  const stock = (reason: string) => ({ vmid: opts.baseVmid, golden: false, reason });
  if (!opts.goldenVmid) return stock("golden templates disabled");
  if (!opts.isGame) return stock("not a game order");
  if (opts.baseVmid !== GOLDEN_SOURCE_VMID) return stock(`catalog base ${opts.baseVmid} is not ${GOLDEN_SOURCE_VMID}`);
  const cfg = opts.nodeConfig;
  if (!cfg) return stock(`node has no vmid ${opts.goldenVmid}`);
  if (String(cfg.template ?? "") !== "1") return stock(`vmid ${opts.goldenVmid} on this node is not a template`);
  const tags = String(cfg.tags ?? "").split(/[;,\s]+/);
  if (!tags.includes(GOLDEN_TAG)) return stock(`vmid ${opts.goldenVmid} is not tagged ${GOLDEN_TAG}`);
  const size = diskSizeGBFromSpec(cfg.scsi0);
  if (size === null) return stock(`could not read the golden template's disk size`);
  if (size > opts.targetDiskGB) return stock(`golden disk ${size}G is larger than the order's ${opts.targetDiskGB}G`);
  return { vmid: opts.goldenVmid, golden: true, reason: `golden template ${opts.goldenVmid}` };
}

/**
 * May this golden clone be a LINKED clone (`full: 0`, a ZFS clone of the
 * template's base snapshot — ~2s instead of a full copy)? Opt-in
 * (NXEON_GOLDEN_LINKED_CLONE=1) and only onto the template's own storage,
 * which a linked clone requires (an HDD-tier order on vmdata-hdd always gets a
 * full copy).
 *
 * Operational consequence, documented in docs/DOCUMENTATION.md: a template
 * with linked clones cannot be destroyed, so a golden rebuild ALWAYS gets a
 * new vmid (which the never-reuse rule requires anyway) and the old one is
 * retired only when its last clone is gone.
 */
export function linkedCloneAllowed(opts: { enabled: boolean; templateDiskSpec: string | null; targetStorage: string }): boolean {
  if (!opts.enabled || !opts.templateDiskSpec) return false;
  const templateStorage = opts.templateDiskSpec.split(":")[0];
  return !!templateStorage && templateStorage === opts.targetStorage;
}
