def p(s): return datetime.fromisoformat(s.replace('Z','+00:00')) if s else None
def pct(a,q):
    a=sorted(a); 
    if not a: return None
    return a[min(len(a)-1,int(round(q*(len(a)-1))))]
print(collections.Counter(r['status'] for r in R))
print(collections.Counter((r['started'] is not None) for r in R))
def stats(rows,label):
    ok=[r for r in rows if r['status']=='DONE' and r['started'] and r['finished']]
    run=[(p(r['finished'])-p(r['started'])).total_seconds() for r in ok]
    q=[(p(r['started'])-p(r['created'])).total_seconds() for r in rows if r['started']]
    n=len(rows); fail=sum(1 for r in rows if r['status']=='FAILED')
    retry=sum(1 for r in rows if r['attempts']>1)
    print(f"{label:28s} n={n:3d} done={len(ok):3d} fail={fail:2d} retried={retry:2d} run med={pct(run,.5) and round(pct(run,.5))} p90={pct(run,.9) and round(pct(run,.9))} min={run and round(min(run))} max={run and round(max(run))} | qwait med={q and round(pct(q,.5))} p90={q and round(pct(q,.9))}")
stats(R,'ALL')
for k in ['isGame']:
    for v in [True,False]: stats([r for r in R if r[k]==v],f'{k}={v}')
fam=collections.defaultdict(list)
for r in R: fam[r['fam']].append(r)
for f,rows in sorted(fam.items(),key=lambda x:-len(x[1])): stats(rows,'fam '+str(f))
nd=collections.defaultdict(list)
for r in R: nd[r['node']].append(r)
for f,rows in sorted(nd.items(),key=lambda x:-len(x[1])): stats(rows,'node '+str(f))
# by month window: last 14d vs earlier
from datetime import timezone,timedelta
now=datetime.now(timezone.utc)
for d in (7,14,30):
    stats([r for r in R if p(r['created'])>now-timedelta(days=d)],f'last {d}d')
# fam x node (games)
fn=collections.defaultdict(list)
for r in R:
    if r['isGame']: fn[(r['fam'],r['node'])].append(r)
print('--- fam x node (n>=3)')
for k,rows in sorted(fn.items(),key=lambda x:-len(x[1])):
    if len(rows)>=3: stats(rows,f'{k[0]}@{k[1]}')
print('--- errors')
c=collections.Counter()
for r in R:
