import json,urllib.request,sys
def get(url,tok=None,accept=None):
    r=urllib.request.Request(url); 
    if tok: r.add_header('Authorization','Bearer '+tok)
    r.add_header('Accept',accept or 'application/vnd.docker.distribution.manifest.list.v2+json, application/vnd.oci.image.index.v1+json, application/vnd.docker.distribution.manifest.v2+json, application/vnd.oci.image.manifest.v1+json')
    return json.load(urllib.request.urlopen(r,timeout=20))
def size(img):
    repo,tag=(img.split(':')+['latest'])[:2]
    if '/' not in repo: repo='library/'+repo
    try:
        tok=json.load(urllib.request.urlopen(f"https://auth.docker.io/token?service=registry.docker.io&scope=repository:{repo}:pull",timeout=20))['token']
        m=get(f"https://registry-1.docker.io/v2/{repo}/manifests/{tag}",tok)
        if 'manifests' in m:
            d=[x for x in m['manifests'] if x.get('platform',{}).get('architecture')=='amd64' and x.get('platform',{}).get('os')=='linux'][0]['digest']
            m=get(f"https://registry-1.docker.io/v2/{repo}/manifests/{d}",tok)
        L=m['layers']; return sum(l['size'] for l in L)/1e6,len(L)
    except Exception as e: return str(e)[:50],0
for i in sys.argv[1:]:
    s,n=size(i); print(i,s if isinstance(s,str) else f"{s:.0f} MB compressed, {n} layers")
EOF
